import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Creating a form","description":"Add a form to a Grid, add fields, and configure the success page.","frontmatter":{"title":"Creating a form","description":"Add a form to a Grid, add fields, and configure the success page."},"headers":[],"relativePath":"en/formulare/formular-erstellen.md","filePath":"en/formulare/formular-erstellen.md","lastUpdated":1787319236000}'),s={name:"en/formulare/formular-erstellen.md"};function i(n,e,l,d,h,m){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="your-first-form" tabindex="-1">Your first form <a class="header-anchor" href="#your-first-form" aria-label="Permalink to &quot;Your first form&quot;">​</a></h1><p>A <strong>Form</strong> is a data entry screen for a Grid. You decide which fields it asks for, what the form looks like, and what happens after it&#39;s submitted.</p><p>People filling out a form don&#39;t need an <strong>ApptiveGrid account</strong> — unless you explicitly restrict access.</p><h2 id="creating-a-form" tabindex="-1">Creating a form <a class="header-anchor" href="#creating-a-form" aria-label="Permalink to &quot;Creating a form&quot;">​</a></h2><ol><li>In the sidebar, open the Grid the data should flow into.</li><li>Under <strong>Forms</strong>, choose <strong>Create form</strong>.</li><li>Give it a name.</li></ol><p>The form starts out empty. With no fields selected, no one can enter anything.</p><div class="tip custom-block"><p class="custom-block-title">A form always belongs to one Grid</p><p>A form writes to exactly one Grid. If data needs to flow into several Grids, you need several forms — or you let a <a href="/en/flows/aktionen">Flow</a> handle the distribution.</p></div><h2 id="adding-fields" tabindex="-1">Adding fields <a class="header-anchor" href="#adding-fields" aria-label="Permalink to &quot;Adding fields&quot;">​</a></h2><p>The editor has three tabs: <strong>Pages</strong>, <strong>Layout</strong>, and <strong>More</strong>. Field selection lives under the <em>Pages</em> tab.</p><p>On the left, under <strong>Available fields</strong>, you&#39;ll find every field of the Grid that isn&#39;t in the form yet.</p><ul><li><strong>Add fields</strong> brings an existing field into the form.</li><li><strong>Create field</strong> creates a <em>new</em> field on the Grid and adds it right away.</li></ul><div class="warning custom-block"><p class="custom-block-title">&quot;Create field&quot; changes the Grid</p><p>This button creates a new column on the Grid — not just something in the form. The column then appears in every view of this Grid.</p></div><p>Not every column type can be collected. <strong>Rich Text</strong>, and the calculated types <strong>Use linked value</strong>, <strong>Calculate sum</strong>, and <strong>Formula</strong>, have no form field. Details in the <a href="/en/referenz/spaltentypen">Column types reference</a>.</p><h2 id="field-settings" tabindex="-1">Field settings <a class="header-anchor" href="#field-settings" aria-label="Permalink to &quot;Field settings&quot;">​</a></h2><p>Clicking <strong>Edit</strong> on a field opens its <strong>Field settings</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>Caption shown in the form. Overrides the column name for this form only.</td></tr><tr><td><strong>Description</strong></td><td>Explanatory text below the label.</td></tr><tr><td><strong>Required field</strong></td><td>The form can&#39;t be submitted while this field is empty.</td></tr><tr><td><strong>Multi-line</strong></td><td>For text fields: several lines instead of one.</td></tr><tr><td><strong>Component type</strong></td><td>For select fields: <em>Dropdown menu</em> or <em>List</em>; for files: <em>Choose file</em> or <em>Record video</em>.</td></tr><tr><td><strong>Allow adding files only</strong></td><td>Existing attachments can&#39;t be deleted.</td></tr><tr><td><strong>Prefilled</strong></td><td>A default value that&#39;s already entered when the form opens.</td></tr><tr><td><strong>Not editable</strong></td><td>The field is shown but can&#39;t be edited.</td></tr><tr><td><strong>Not visible</strong></td><td>The field is not shown but is still submitted.</td></tr><tr><td><strong>Enable barcode scanner</strong></td><td>Allows filling the field via camera scan.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">&quot;Not visible&quot; and &quot;Prefilled&quot; go together</p><p>A hidden field only becomes useful once it has a value. Example: a hidden <em>Source</em> field is filled with <code>Newsletter</code> via a <a href="/en/formulare/vorausgefuellte-links">prefilled link</a> — the person filling out the form sees nothing of it, but you later know where the submission came from.</p></div><div class="warning custom-block"><p class="custom-block-title">Hidden fields are not confidential</p><p><em>Not visible</em> hides a field in the interface. That does not make it secret. Don&#39;t put data there that the person filling out the form shouldn&#39;t see.</p></div><p>Four of these settings are plan-dependent: <em>Not editable</em>, <em>Not visible</em>, <em>Prefilled</em>, and <em>Enable barcode scanner</em>.</p><h2 id="text-and-text-blocks" tabindex="-1">Text and text blocks <a class="header-anchor" href="#text-and-text-blocks" aria-label="Permalink to &quot;Text and text blocks&quot;">​</a></h2><p>Above the form sit <strong>Form title</strong> and <strong>Description</strong>.</p><p>Use <strong>Create text block</strong> to place explanatory sections between fields. A text block is either a <strong>Heading</strong> or a <strong>Paragraph</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Structure long forms</p><p>Heading text blocks are the simplest way to keep a form from becoming cluttered. From around ten fields onward, <a href="/en/formulare/mehrseitige-formulare">multiple form pages</a> are worth considering instead.</p></div><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><p>In the <strong>Layout</strong> tab, you set:</p><ul><li><strong>Text</strong> — title, description, <em>submit button text</em></li><li><strong>Images and logo</strong> — <em>background image</em> and <em>logo</em> with <em>width</em> (as a percentage of the form width)</li><li><strong>Colors</strong> — <em>primary color</em>, <em>button color</em>, <em>background color</em>, <em>card background color</em>, <em>header color</em>, <em>card without shadow</em></li><li><strong>Field style</strong> — <em>No border</em> or <em>With border</em></li></ul><div class="tip custom-block"><p class="custom-block-title">A logo is plan-dependent</p><p>Your own logo is only available on the top plan. Background image and colors are available on every plan.</p></div><h2 id="what-happens-after-submitting" tabindex="-1">What happens after submitting <a class="header-anchor" href="#what-happens-after-submitting" aria-label="Permalink to &quot;What happens after submitting&quot;">​</a></h2><p>The <strong>Success page</strong> section determines what the person filling out the form sees afterward.</p><p>By default it shows <em>Thank you!</em> with the text <em>Your response has been received.</em> Change both via <strong>Title</strong> and <strong>Message</strong>.</p><p>Below that, you choose an <strong>Action</strong>:</p><table tabindex="0"><thead><tr><th>Action</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>No action</strong></td><td>The success message stays as-is.</td></tr><tr><td><strong>Fill out again</strong></td><td>A button reopens the form — for entering several submissions in a row.</td></tr><tr><td><strong>Redirect to website</strong></td><td>Redirects to a <strong>website</strong> you specify.</td></tr></tbody></table><p>For the last two, you also set the <strong>Trigger</strong>:</p><ul><li><strong>Click button</strong> — the person decides</li><li><strong>Immediately after submitting</strong> — right away</li><li><strong>after 5 seconds</strong> — the success message stays visible briefly</li></ul><div class="tip custom-block"><p class="custom-block-title">Choose the redirect carefully</p><p><em>Immediately after submitting</em> skips the success message entirely. The person then sees no confirmation that anything arrived. <em>After 5 seconds</em> is usually the better choice.</p></div><p>The redirect option is plan-dependent.</p><h2 id="hiding-the-product-notice" tabindex="-1">Hiding the product notice <a class="header-anchor" href="#hiding-the-product-notice" aria-label="Permalink to &quot;Hiding the product notice&quot;">​</a></h2><p>Forms carry a default notice, <em>Create your own free form with …</em>. <strong>Hide product notice</strong> removes it. This is also plan-dependent.</p><h2 id="more-settings" tabindex="-1">More settings <a class="header-anchor" href="#more-settings" aria-label="Permalink to &quot;More settings&quot;">​</a></h2><p>In the <strong>More</strong> tab:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Save to continue later</strong></td><td>People filling out the form can pause and resume later. → <a href="/en/formulare/speichern-und-fortsetzen">Details</a></td></tr><tr><td><strong>Auto-submit</strong></td><td>The form submits itself as soon as it loads — for example to start a Flow via a QR code scan.</td></tr><tr><td><strong>Hide submit button</strong></td><td>Useful when the form should only display an entry&#39;s data.</td></tr><tr><td><strong>Show account confirmation notice</strong></td><td>Shows which account the person is signed in as. Useful on shared devices.</td></tr><tr><td><strong>Multiple languages</strong></td><td>Maintain form text in several languages. → <a href="/en/formulare/mehrsprachig">Details</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Auto-submit needs complete prefill data</p><p>If the form submits itself, no one gets the chance to fill in required fields. All the needed values must therefore be set via <em>Prefilled</em> or a prefilled link.</p></div><h2 id="preview-and-publishing" tabindex="-1">Preview and publishing <a class="header-anchor" href="#preview-and-publishing" aria-label="Permalink to &quot;Preview and publishing&quot;">​</a></h2><p><strong>Preview in new tab</strong> shows you the form exactly as people filling it out will see it.</p><p>To distribute it, use <strong>Create link</strong> to generate a share link. Only then is the form reachable. Every way of sharing it is described in <a href="/en/formulare/formular-teilen">Sharing a form</a>.</p><h2 id="what-people-filling-it-out-see" tabindex="-1">What people filling it out see <a class="header-anchor" href="#what-people-filling-it-out-see" aria-label="Permalink to &quot;What people filling it out see&quot;">​</a></h2><p>For reference, the labels in the finished form:</p><table tabindex="0"><thead><tr><th>Element</th><th>Text</th></tr></thead><tbody><tr><td>Submit</td><td><em>Submit</em></td></tr><tr><td>Next form page</td><td><em>Next</em></td></tr><tr><td>Previous form page</td><td><em>Back</em></td></tr><tr><td>After submitting</td><td><em>Thank you!</em> / <em>Your response has been received.</em></td></tr><tr><td>Another response</td><td><em>Send another response</em></td></tr><tr><td>Signature field</td><td><em>Tap here to sign</em></td></tr><tr><td>Voice recording</td><td><em>Tap here to record</em></td></tr><tr><td>Error</td><td><em>Oops - Error</em></td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>Every form carries the notice <em>Never share your password.</em></p><div class="danger custom-block"><p class="custom-block-title">Never collect passwords or payment details</p><p>Never ask for passwords, credentials, or full payment details in a form. ApptiveGrid explicitly tells people filling out forms not to enter such information — and shows a warning or locks conspicuous forms.</p><p>Abusive forms can be reported via <strong>Report form</strong>. Contact: <code>abuse@apptivegrid.com</code>.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/felder-konfigurieren">Configuring fields</a></li><li><a href="/en/formulare/mehrseitige-formulare">Multi-page forms</a></li><li><a href="/en/formulare/formular-teilen">Sharing a form</a></li><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li></ul>',53)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
